const j=$input.first().json??{};

const pagina=j.pagina??null;
const numeroOrden=j.numero_orden??null;
const nombreFichero=j.nombre_fichero??null;
const archivoId=j.archivo_id??"catalogo_actual";

let texto="";

if(typeof j.data==="string"){
  texto=j.data;
}else if(typeof j.body==="string"){
  texto=j.body;
}else if(typeof j.text==="string"){
  texto=j.text;
}else if(typeof j.texto==="string"){
  texto=j.texto;
}else{
  texto="";
}

texto=String(texto)
  .replace(/\r/g,"\n")
  .replace(/\n{3,}/g,"\n\n")
  .replace(/[ \t]{2,}/g," ")
  .trim();

return [{
  json:{
    pagina,
    numero_orden:numeroOrden,
    nombre_fichero:nombreFichero,
    archivo_id:archivoId,
    texto,
    texto_length:texto.length
  }
}];

const items=$input.all();

const sorted=items.sort((a,b)=>{
  const ai=a.json.chunk_index??0;
  const bi=b.json.chunk_index??0;
  return ai-bi;
});

let lineas=[];

for(const item of sorted){
  const texto=String(item.json.texto??"");
  const partes=texto.split(/\r?\n/);

  for(const parte of partes){
    const linea=parte.trim();
    if(!linea) continue;

    const anterior=lineas[lineas.length-1]??"";

    // Une líneas partidas tipo:
    // "... 100ml 16" + "9 €" => "... 100ml 169 €"
    const anteriorPareceCortado=/\b\d+\s*(?:ml|mI|l|I)\s+\d{1,2}$/.test(anterior);
    const lineaPareceRestoPrecio=/^\d{1,2}\s*€$/.test(linea);

    if(anteriorPareceCortado&&lineaPareceRestoPrecio){
      lineas[lineas.length-1]=anterior+linea.replace(/\s+/g,"");
    }else{
      lineas.push(linea);
    }
  }
}

return [{
  json:{
    archivo_id:sorted[0]?.json.archivo_id??"catalogo_actual",
    total_chunks:sorted.length,
    texto:lineas.join("\n")
  }
}];

const perfumes=$json.perfumes||[];

function escapeHtml(value){
  return String(value??"")
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;")
    .replace(/'/g,"&#039;");
}

if(!Array.isArray(perfumes)||perfumes.length===0){
  const html='<!doctype html><html><head><meta charset="utf-8"></head><body><h1>Sin perfumes válidos</h1></body></html>';
  const binaryData=await this.helpers.prepareBinaryData(Buffer.from(html,"utf8"),"catalogo_perfumes.html","text/html");
  return[{json:{error:true,motivo:"No hay perfumes en $json.perfumes",total_perfumes:0,fileName:"catalogo_perfumes.html",html},binary:{data:binaryData}}];
}

const filas=perfumes.map(p=>`<tr><td>${escapeHtml(p.marca)}</td><td>${escapeHtml(p.modelo)}</td><td>${escapeHtml(p.sexo)}</td><td>${escapeHtml(p.tipo)}</td><td>${escapeHtml(p.tamano)}</td><td class="precio">${escapeHtml(p.precio)} €</td></tr>`).join("");

const notas=`<div class="notas"><p><strong>Los perfumes tardan aprox. 1 mes en llegar. Se pagan por anticipado. Portes gratis a partir de 300€ con GLS asegurado.</strong></p><p><strong>Nota 1:</strong> La "T" significa "téster" o "probador". Perfume original, nuevo, en caja blanca, marrón o sin caja y, a veces, sin tapón ornamental.</p><p><strong>Nota 2:</strong> Las referencias sombreadas en gris son regulares precintados, tal y como los compras en las perfumerías.</p><p><strong>Nota 3:</strong> La "R Caja Dañada" significa "Regular con la caja dañada". Perfume y caja original, nuevo, con la caja dañada y/o sin celofán.</p><p><strong>Nota 4:</strong> Las marcas sombreadas en color cian son marcas de perfumes nicho y árabes.</p></div>`;

const html=`<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:10mm}body{font-family:Arial,sans-serif;font-size:8.5px;color:#111;background:#fff;margin:0}h1{font-size:16px;margin:0 0 6px 0;text-align:center}.total{margin:0 0 6px 0;text-align:center;font-weight:bold}.notas{font-size:8.3px;margin:0 0 8px 0;border:1px solid #bbb;padding:5px;background:#f7f7f7}.notas p{margin:0 0 3px 0;line-height:1.25}.notas p:last-child{margin-bottom:0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #999;padding:3px;text-align:left;vertical-align:top;word-wrap:break-word}th{background:#eee;font-weight:bold}.marca{width:20%}.modelo{width:44%}.sexo{width:8%}.tipo{width:8%}.tamano{width:10%}.precio{width:10%;text-align:right;font-weight:bold}</style></head><body><h1>Catálogo perfumes</h1><p class="total">Total perfumes: ${perfumes.length}</p>${notas}<table><thead><tr><th class="marca">Marca</th><th class="modelo">Modelo</th><th class="sexo">Sexo</th><th class="tipo">Tipo</th><th class="tamano">Tamaño</th><th class="precio">Precio</th></tr></thead><tbody>${filas}</tbody></table></body></html>`;

const binaryData=await this.helpers.prepareBinaryData(Buffer.from(html,"utf8"),"catalogo_perfumes.html","text/html");

return[{json:{fileName:"catalogo_perfumes.html",total_perfumes:perfumes.length,html},binary:{data:binaryData}}];

